"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * CHECKBOX: a tick that draws itself
 *
 *   check    the box fills from its centre (a slight overshoot)
 *            and the tick draws itself along its stroke
 *   uncheck  the tick retracts the way it came, the fill shrinks
 *   mixed    a dash grows from the middle; mixed → checked bends
 *            the dash into the tick
 *   press    the box gives under the finger
 *
 * A real <input type="checkbox"> underneath, so forms, labels,
 * Space and screen readers all work as they always do.
 * ───────────────────────────────────────────────────────── */

export interface CheckboxProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "type" | "size" | "checked" | "defaultChecked"
> {
  checked?: boolean | "mixed";
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  label?: React.ReactNode;
  description?: React.ReactNode;
  /** 14px or 16px box. */
  size?: "sm" | "md";
  ref?: React.Ref<HTMLInputElement>;
}

export function Checkbox({
  checked,
  defaultChecked = false,
  onCheckedChange,
  label,
  description,
  size = "md",
  disabled,
  className = "",
  onChange,
  ref,
  id,
  ...props
}: CheckboxProps) {
  const reduced = useInteractionReducedMotion();
  const auto = React.useId();
  const inputId = id ?? auto;
  const inner = React.useRef<HTMLInputElement>(null);
  const [own, setOwn] = React.useState(defaultChecked);
  const state = checked !== undefined ? checked : own;
  const on = state === true;
  const mixed = state === "mixed";

  React.useEffect(() => {
    if (inner.current) inner.current.indeterminate = mixed;
  }, [mixed]);

  const box = size === "sm" ? "size-3.5 rounded-[4px]" : "size-4 rounded-[5px]";
  const t = (ms: number, delay = 0, ease = EASE_OUT) =>
    reduced ? "none" : `${ms}ms ${ease} ${delay}ms`;

  return (
    <label
      htmlFor={inputId}
      className={`group/cb inline-flex select-none items-start gap-2.5 ${disabled ? "cursor-default opacity-50" : "cursor-pointer"} ${className}`}
    >
      <span className={`relative mt-[2px] inline-flex shrink-0 ${box}`}>
        <input
          ref={(el) => {
            inner.current = el;
            if (typeof ref === "function") ref(el);
            else if (ref)
              (ref as React.RefObject<HTMLInputElement | null>).current = el;
          }}
          id={inputId}
          type="checkbox"
          checked={on}
          disabled={disabled}
          aria-checked={mixed ? "mixed" : on}
          onChange={(e) => {
            if (checked === undefined) setOwn(e.target.checked);
            onChange?.(e);
            onCheckedChange?.(e.target.checked);
          }}
          className="peer absolute inset-0 m-0 size-full cursor-[inherit] appearance-none rounded-[inherit] outline-none"
          {...props}
        />
        {/* The box: a thin line that the fill grows over. */}
        <span
          aria-hidden="true"
          className={`pointer-events-none absolute inset-0 rounded-[inherit] bg-background shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,var(--border))] transition-[box-shadow,scale] duration-200 group-hover/cb:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_40%,var(--border))] group-active/cb:scale-[0.88] peer-focus-visible:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_20%,transparent)] motion-reduce:group-active/cb:scale-100`}
        >
          <span
            className="absolute inset-0 rounded-[inherit] bg-primary"
            style={{
              transform: on || mixed ? "scale(1)" : "scale(0.4)",
              opacity: on || mixed ? 1 : 0,
              transition: reduced
                ? "none"
                : `transform ${t(320, 0, EASE_THROW)}, opacity ${t(160)}`,
            }}
          />
          <svg
            viewBox="0 0 16 16"
            fill="none"
            className="absolute inset-0 size-full text-primary-foreground"
          >
            {/* The tick draws on the way in and retracts on the way out. */}
            <path
              d="M4 8.4 6.8 11 12 5.2"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength={1}
              strokeDasharray={1}
              style={{
                strokeDashoffset: on ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `stroke-dashoffset ${on ? t(300, 90) : t(160)}`,
              }}
            />
            <path
              d="M4.5 8h7"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              style={{
                transform: mixed ? "scaleX(1)" : "scaleX(0)",
                transformOrigin: "8px 8px",
                transition: reduced
                  ? "none"
                  : `transform ${t(260, mixed ? 60 : 0)}`,
              }}
            />
          </svg>
        </span>
      </span>
      {(label || description) && (
        <span className="flex min-w-0 flex-col gap-0.5">
          {label && (
            <span className="text-[13.5px] font-medium leading-5 text-foreground">
              {label}
            </span>
          )}
          {description && (
            <span className="text-[12.5px] leading-snug text-muted-foreground">
              {description}
            </span>
          )}
        </span>
      )}
    </label>
  );
}

export default Checkbox;

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

